function cpState(){
  var t=tfS();
  if(!t.cp) t.cp={v:1,spot:1000,copies:[]}; /* 데모 스팟 잔고 $1000 시드 */
  if(!Array.isArray(t.cp.copies)) t.cp.copies=[];
  if(t.cp.spot==null) t.cp.spot=1000;
  return t.cp;
}
function cpFind(id){ return cpState().copies.find(function(x){ return x.id===id; })||null; }
function cpStart(ne){
  if(!S.user){ authOpen('signup'); return; } /* 상태 변경 경계의 로그인 가드 — 딥링크 우회 차단 (codex P2-12) */
  if(typeof tfAiGate==='function'&&!tfAiGate()) return; /* 관망 중 신규 전략 복사 금지 */
  if(!tfDerive().entitlement.follow){ tfAcSheet('bitget'); return; }
  if(!$('cps-amt')||!cpFormSync()){ toast('입력을 확인해주십시오'); return; }
  var nick; try{ nick=decodeURIComponent(ne); }catch(e){ return; }
  var s2=tfSSFind(nick); if(!s2||s2.me) return;
  nick=s2.nick; /* ID 나 옛 이름으로 들어와도 같은 전략으로 저장 */
  if(cpState().copies.some(function(x){ return x.nick===nick&&x.status==='active'; })){ /* 전략당 활성 전략 복사 1건 */
    toast('이미 이 전략을 따라가고 있습니다. 복사한 전략 탭에서 관리할 수 있습니다');
    mkFollowClose(true); TF_ONSHARE=false; try{ history.replaceState(null,'',location.pathname+location.search); }catch(e){} tfShareHub('follow'); return;
  }
  var amt=parseFloat($('cps-amt').value);
  var cp=cpState();
  var mainPair=CPP_PAIR[s2.asset]||s2.asset;
  var eqA=s2.r.eq||[];
  var c2={id:'cp'+Date.now(), nick:nick, mode:'ratio', amount:amt, pairs:(TF_CPS.pairs||[mainPair]).slice(),
    gen:{asof:MK_ASOF.slice(),len:PRICE0.length},
    simStartI:eqA.length>31?eqA[eqA.length-31].i:null, /* 데모: 시작을 30봉 전으로 시뮬 (표기: 시뮬레이션) */
    adv:{marginMode:'follow',lev:'follow',slip:'sys',maxMarginPct:TF_MKF.cap||95,maxPosX:5,maxLoss:TF_MKF.loss||-20,existing:TF_MKF.existing||'skip'},
    at:Date.now(), status:'active', ledger:[{at:Date.now(),type:'add',amt:amt,i:eqA.length>31?eqA[eqA.length-31].i:null}]}; /* 입출금은 append-only, 예산은 기존 스팟 배분 로직 그대로 */
  cp.spot=Math.max(0,cp.spot-amt);
  cp.copies.push(c2);
  tfSaveNow();
  tfTrack('cp_start',{nick:nick,amt:amt,maxLoss:c2.adv.maxLoss});
  mkFollowClose(true);
  toast(nick+' 전략 복사를 시작했습니다. '+(c2.adv.existing==='copy'?'지금 든 종목부터 바로 따라갑니다':'다음 진입부터 자동으로 따라갑니다'));
  TF_ONSHARE=false;
  try{ history.replaceState(null,'',location.pathname+location.search); }catch(e){}
  tfShareHub('follow');
}
function cpAdjCommit(cid,v,dir){
  var c2=cpFind(cid), cp=cpState(); if(!c2) return;
  if(dir==='add'){ if(v>cp.spot){ toast('사용 가능 금액이 부족합니다'); return; } cp.spot-=v; }
  else { cp.spot+=v; }
  var s2l=tfSSFind(c2.nick), eqL=s2l&&s2l.r&&s2l.r.eq; c2.ledger.push({at:Date.now(),type:dir,amt:v,i:eqL&&eqL.length?eqL[eqL.length-1].i:null}); /* append-only. i = 그 시점 봉 (D34: 반영 시점과 기준가의 기준) */
  TF_CPA.confirmed=false;
  tfSaveNow(); tfSS3DlgClose();
  tfTrack('cp_adjust',{id:cid,dir:dir,amt:v});
  toast(dir==='add'?cpUsd(v,0)+'를 예산에 추가했습니다':cpUsd(v,0)+'를 회수했습니다');
  if(G.mode==='tfss3') tfShareHub('follow');
  else if(G.mode==='tfcpx') cpDetailView(cid,'bal'); /* 상세에서 조정하면 자금 이동 탭으로 (cp 5단계) */
}
function cpFlat(cid){
  var c2=cpFind(cid); if(!c2||c2.status!=='active') return;
  var s2=tfSSFind(c2.nick); if(!s2||!s2.r.eq||!s2.r.eq.length) return;
  tfTrack('cp_flat',{id:cid});
  if(c2.winding){ cpClose(cid); return; } /* 정산은 cpClose 한 곳에서: 보유 실현, 봉 고정, 반환 한 번 */
  { var fb=s2.r.eq[s2.r.eq.length-1].i; if(!c2.flats) c2.flats=c2.flatI!=null?[c2.flatI]:[]; if(c2.flats.indexOf(fb)<0) c2.flats.push(fb); c2.flatI=fb; } /* 정리한 봉을 차례로 남긴다 */
  tfSaveNow(); tfSS3DlgClose();
  toast('포지션을 정리했습니다. 다음 진입부터 다시 따라갑니다');
  cpDetailView(cid,'pos');
}
function mkStopGo(cid,mode){
  var c2=cpFind(cid); if(!c2||c2.status!=='active') return;
  c2.stopMode=MK_STOP_L[mode]?mode:'now';
  var d=cpCalc(c2);
  if(c2.stopMode==='now'||!d.posOpen||d.missing){ cpClose(cid); return; }
  c2.winding=true; c2.windAt=Date.now(); { var sw=tfSSFind(c2.nick); if(sw&&sw.r&&sw.r.eq&&sw.r.eq.length) c2.stopI=sw.r.eq[sw.r.eq.length-1].i; }
  tfSaveNow(); tfSS3DlgClose();
  toast('새 진입을 멈췄습니다. 열린 포지션은 '+(c2.stopMode==='wait'?'원본 전략이 청산할 때 함께 정리합니다':'내가 정리할 때까지 남아 있습니다'));
  if(location.hash.indexOf('#/share/c/')===0) cpDetailView(cid,'pos'); else tfShareHub('follow');
}
function cpClose(cid,silent){
  var c2=cpFind(cid), cp=cpState(); if(!c2||c2.status!=='active') return;
  var s2=tfSSFind(c2.nick);
  if(s2&&s2.r&&s2.r.eq&&s2.r.eq.length) c2.endI=s2.r.eq[s2.r.eq.length-1].i;
  var d=cpCalc(c2), back=Math.max(0,d.est);
  c2.status='closed'; c2.closedAt=Date.now(); c2.settle={net:d.net,share:d.share,back:back};
  c2.ledger.push({at:Date.now(),type:'out',amt:back,i:c2.endI});
  cp.spot+=back;
  tfSaveNow(); tfSS3DlgClose();
  tfTrack('cp_close',{id:cid,net:d.net});
  if(silent) return;
  toast('전략 복사를 중단했습니다'+(c2.stopMode&&c2.stopMode!=='now'?' ('+MK_STOP_L[c2.stopMode]+')':'')+'. '+cpUsd(back,0)+'가 예산으로 돌아왔습니다');
  tfShareHub('follow');
}
